function wrapText(c,text,x,y,maxWidth,lineHeight){const paras=String(text).split('\n');for(const para of paras){let line='';for(const word of para.split(' ')){const next=line?line+' '+word:word;if(c.measureText(next).width>maxWidth&&line){c.fillText(line,x,y);line=word;y+=lineHeight;}else line=next;}c.fillText(line,x,y);y+=lineHeight;}return y;}
