function contactTool(e){if(e.pointerType==='pen'&&(PenEngine.isEraser(e)||(penPrefs.sideButton==='eraser'&&PenEngine.isSideButton(e))))return'eraser';return tool;}
function eraseAt(p){const radius=penPrefs.eraserSize,previous=lastErasePoint||p,steps=Math.min(100,Math.max(1,Math.ceil(Math.hypot(p.x-previous.x,p.y-previous.y)/(radius*.5))));for(let i=1;i<=steps;i++){const sample={x:previous.x+(p.x-previous.x)*i/steps,y:previous.y+(p.y-previous.y)*i/steps},result=InkTools.erase(current().objects,sample,radius,penPrefs.eraserMode);if(result.changed){if(!eraseChanged){pushHistory();editor?.clear();lasso?.clear();eraseChanged=true;}current().objects=result.objects;invalidateBoard();}}lastErasePoint=p;requestBoardRender();}
function startGesture(e,p,activeTool){pointerId=e.pointerId;gestureTool=activeTool;activePointerType=e.pointerType;try{canvas.setPointerCapture(e.pointerId);}catch{}if(activeTool==='eraser'){eraseChanged=false;lastErasePoint=null;eraseAt(p);return;}if(activeTool==='select'){editor.handleDown(e,p);return;}if(activeTool==='lasso'){lasso.handleDown(e,p);return;}if(activeTool==='laser'||activeTool==='spotlight'){effects[activeTool](p);return;}if(activeTool==='text'){pointerId=null;gestureTool=null;textDialog(p);return;}if(activeTool==='hand'){pointerId=null;gestureTool=null;return;}pushHistory('append');if(['line','rectangle','circle'].includes(activeTool))drawing={type:activeTool,x:p.x,y:p.y,x2:p.x,y2:p.y,color:ink,width};else drawing=PenEngine.createStroke({tool:activeTool,color:ink,width:activeTool==='highlight'?width*6:width,settings:penSettings,opacity:penPrefs.opacity},p);if(liveInk&&drawing.type==='stroke'){liveInk.setColor(visibleInk(drawing.color));liveInk.begin(drawing);$('#board-empty').hidden=true;$('#pen-cursor').getContext('2d').clearRect(0,0,1600,1000);updateRecordingFrame();}else render(false);}
function updatePenHover(e){if(e.pointerType==='pen'){penNear=true;lastPenSeen=Date.now();lastPenData=PenEngine.point(e);lastPenData.buttons=e.buttons||0;lastPenData.pointerType='pen';}if(e.pointerType==='pen'||e.pointerType==='mouse'){cursorPoint=point(e);if(pointerId===null&&!hoverFrame)hoverFrame=requestAnimationFrame(()=>{hoverFrame=null;if(pointerId===null)drawPenCursor(e);});}}
canvas.addEventListener('pointerover',updatePenHover);
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&$('#pen-only').checked){e.preventDefault();return;}if(pointerId!==null)return;const isPen=e.pointerType==='pen';if(e.button!==0&&!isPen)return;if(isPen&&(e.pressure==null||e.pressure===0)&&!(e.buttons&1)&&!PenEngine.isEraser(e))return;const p=point(e);if(p.x<0||p.x>1600||p.y<0||p.y>1000)return;e.preventDefault();updatePenHover(e);startGesture(e,p,contactTool(e));});
canvas.addEventListener('pointermove',e=>{updatePenHover(e);if(pointerId===null){if(tool==='laser')effects?.laser(point(e));if(tool==='spotlight')effects?.spotlight(point(e));return;}if(e.pointerId!==pointerId)return;const p=point(e);if(['pen','highlight','eraser'].includes(gestureTool)&&e.pointerType==='pen'&&['pen','highlight','eraser'].includes(tool)){const desired=contactTool(e);if(desired!==gestureTool){finishStroke(e);startGesture(e,p,desired);return;}}if(gestureTool==='eraser'){const batch=e.getCoalescedEvents?.(),events=batch?.length?batch:[e],rect=canvas.getBoundingClientRect();for(const ev of events)eraseAt(point(ev,rect));return;}if(gestureTool==='select'){editor.handleMove(e,p);return;}if(gestureTool==='lasso'){lasso.handleMove(e,p);return;}if(gestureTool==='laser'||gestureTool==='spotlight'){effects[gestureTool](p);return;}if(!drawing)return;const batch=e.getCoalescedEvents?.(),rect=canvas.getBoundingClientRect();for(const ev of batch?.length?batch:[e]){const next=point(ev,rect);if(drawing.type==='stroke')PenEngine.append(drawing,next);else{drawing.x2=next.x;drawing.y2=next.y;if(drawing.type==='circle'&&penPrefs.perfectCircle){const d=Math.max(Math.abs(next.x-drawing.x),Math.abs(next.y-drawing.y));drawing.x2=drawing.x+Math.sign(next.x-drawing.x||1)*d;drawing.y2=drawing.y+Math.sign(next.y-drawing.y||1)*d;}if(drawing.type==='line'&&penPrefs.angleSnap){const length=Math.hypot(next.x-drawing.x,next.y-drawing.y),angle=Math.round(Math.atan2(next.y-drawing.y,next.x-drawing.x)/(Math.PI/12))*Math.PI/12;drawing.x2=drawing.x+Math.cos(angle)*length;drawing.y2=drawing.y+Math.sin(angle)*length;}}}requestBoardRender();});
function finishStroke(e){if(e.pointerId!==pointerId||pointerId===null)return;if(gestureTool==='select')editor.handleUp();else if(gestureTool==='lasso')lasso.handleUp();else if(gestureTool==='eraser'){if(eraseChanged)save();}else if(drawing){if(drawing.type==='stroke'){if(e.type==='pointerup'&&Number.isFinite(e.clientX)&&Number.isFinite(e.clientY))PenEngine.append(drawing,point(e));PenEngine.finish(drawing);liveInk?.finish(drawing);if(penPrefs.autoShape&&drawing.tool==='pen')drawing=PenEngine.recognizeShape(drawing)||drawing;}current().objects.push(drawing);if(!baseDirty)drawObject(drawing,baseContext);save();}drawing=null;pointerId=null;gestureTool=null;activePointerType=null;eraseChanged=false;lastErasePoint=null;liveInk?.clear();render(baseDirty);}
