function illustrations(){const types=[['triangle','Heron’s triangle','13, 14, 15 sides + height'],['unitcircle','Unit circle','Angle, sine and cosine'],['parabola','Quadratic curve','Roots and turning point'],['derivative','Tangent & derivative','A curve and its local slope'],['integral','Integral symmetry','Two curves, one identity']];openModal('Make the idea visible','<p class="modal-intro">Choose an annotated illustration to explain with your pen. Diagrams are drawn precisely and work offline.</p><div class="shape-buttons"><button data-shape="line">╱ Line</button><button data-shape="rectangle">▭ Rectangle</button><button data-shape="circle">◯ Ellipse / circle</button></div><h3 class="modal-subhead">Illustration library</h3><label class="field">Unit-circle angle: <span id="angle-value">150°</span><input type="range" id="diagram-angle" min="0" max="360" value="150"></label><div class="card-grid">'+types.map(t=>'<button class="choice-card" data-diagram="'+t[0]+'"><canvas width="400" height="250" data-preview="'+t[0]+'"></canvas><strong>'+t[1]+'</strong><small>'+t[2]+'</small></button>').join('')+'</div><div class="notice">For custom illustrations or textbook questions, use the image button on the board to import a photo, screenshot or diagram.</div>','VISUAL ILLUSTRATIONS');function previews(){const angle=+$('#diagram-angle').value;$('#angle-value').textContent=angle+'°';$$('[data-preview]').forEach(c=>MathTools.drawDiagram(c.getContext('2d'),{x:0,y:0,w:400,h:250},c.dataset.preview,{angle}));}$('#diagram-angle').oninput=previews;$$('[data-diagram]').forEach(b=>b.onclick=()=>{const angle=+$('#diagram-angle').value;pushHistory();current().objects.push({type:'diagram',diagram:b.dataset.diagram,options:{angle},x:350,y:250,w:900,h:640});render();save();closeModal();toast('Illustration added. Use the pen to explain or label it.');});$$('[data-shape]').forEach(b=>b.onclick=()=>{setTool(b.dataset.shape);closeModal();toast('Drag on the board to draw your '+b.dataset.shape+'.');});previews();}
$('#shapes-btn').onclick=illustrations;
function calculator(){openModal('Work it out, together.','<p class="modal-intro">Scientific calculations, ready when you need them. Trig functions use radians; log is base 10 and ln is natural log.</p><label class="field">Expression<input id="calc-input" value="sqrt(13^2 + 12^2)" autocomplete="off" spellcheck="false"></label><div id="calc-output" class="calculator-result">—</div><div id="calc-error" class="error-text"></div><div class="calc-keys">'+['sin(','cos(','tan(','sqrt(','^','7','8','9','(',')','4','5','6','*','/','1','2','3','+','-','0','.','pi','⌫','='].map(k=>'<button data-key="'+esc(k)+'">'+esc(k)+'</button>').join('')+'</div><div class="modal-actions"><button class="button primary" id="calc-solve">Calculate</button><button class="button outline" id="calc-insert">Add result to board</button></div>','SCIENTIFIC CALCULATOR');let result;function solve(){try{result=MathTools.calc($('#calc-input').value);if(!Number.isFinite(result))throw Error('This expression has no finite real result.');$('#calc-output').textContent=Number(result.toPrecision(12)).toString();$('#calc-error').textContent='';return true;}catch(e){$('#calc-error').textContent=e.message;$('#calc-output').textContent='—';return false;}}$('#calc-solve').onclick=solve;$('#calc-input').onkeydown=e=>{if(e.key==='Enter')solve();};$$('[data-key]').forEach(b=>b.onclick=()=>{const input=$('#calc-input'),k=b.dataset.key;if(k==='=')return solve();if(k==='⌫')input.value=input.value.slice(0,-1);else input.value+=k;input.focus();});$('#calc-insert').onclick=()=>{if(!solve())return;pushHistory();current().objects.push({type:'text',text:$('#calc-input').value+' = '+$('#calc-output').textContent,x:120,y:200,size:36,serif:true,color:ink,maxWidth:1350});render();save();closeModal();};solve();}
function practiceCorner(){openModal('A question to get them thinking.','<p class="modal-intro">Choose a worked lesson to see its practice question. Reveal the answer when your class is ready.</p><label class="field">Practice from<select id="practice-select">'+Curriculum.lessons.map(l=>'<option value="'+l.id+'" '+(l.id===lesson.id?'selected':'')+'>'+(l.classLevel==='JEE'?'JEE':'Class '+l.classLevel)+' · '+esc(l.title)+'</option>').join('')+'</select></label><div id="practice-body"></div>','PRACTICE CORNER');function show(){const l=Curriculum.lessons.find(l=>l.id===$('#practice-select').value);$('#practice-body').innerHTML='<div class="formula" style="font-size:23px;padding:28px">'+esc(l.practice.question)+'</div><label class="field">Your working<textarea placeholder="Type an answer or work it out on the board…"></textarea></label><div class="modal-actions"><button id="show-practice" class="button primary">Reveal answer</button><button id="board-practice" class="button outline">Put question on board</button></div><div id="full-answer" class="practice-answer" hidden><strong>'+esc(l.practice.answer)+'</strong><br>'+esc(l.practice.hint)+'</div>';$('#show-practice').onclick=()=>$('#full-answer').hidden=false;$('#board-practice').onclick=()=>{addBlank('Practice · '+l.title);current().objects=[{type:'text',text:'LET’S THINK TOGETHER · '+(l.classLevel==='JEE'?'IIT JEE':'CLASS '+l.classLevel),x:100,y:100,size:19,color:'#93a284'},{type:'text',text:l.practice.question,x:100,y:220,size:42,serif:true,color:'#416145',maxWidth:1370,lineHeight:65}];render();save();closeModal();};}$('#practice-select').onchange=show;show();}
function exportDialog(){openModal('Let your lesson travel.','<p class="modal-intro">Export your teaching materials. Notebook backups include every page, drawing and imported image. Recordings have separate video downloads.</p><div class="export-cards"><button id="export-complete"><strong>↓ Teaching backup · .mgm</strong><small>All notebooks, original question files, optional videos.</small></button><button id="export-png"><strong>↓ Current page as PNG</strong><small>A crisp image to share with students.</small></button><button id="export-pdf"><strong>↗ Print / Save as PDF</strong><small>All notebook pages, ready to print. Choose Save as PDF in the print menu.</small></button><button id="export-backup"><strong>↓ Notebook backup</strong><small>Save an editable .json file. Restore it on another device.</small></button><button id="import-backup"><strong>↑ Restore notebook</strong><small>Import a backup as new pages in this notebook.</small></button></div>');$('#export-complete').onclick=fullBackupDialog;$('#export-png').onclick=()=>{canvas.toBlob(b=>{if(b)download(b,safeName($('#board-title').value)+'-page-'+(pageIndex+1)+'.png');},'image/png');};$('#export-backup').onclick=()=>download(new Blob([JSON.stringify(snapshot())],{type:'application/json'}),'mathematics-gyaan-maath-notebook-'+new Date().toISOString().slice(0,10)+'.json');$('#import-backup').onclick=()=>$('#backup-input').click();$('#export-pdf').onclick=async()=>{closeModal();const previous=pageIndex,area=document.createElement('div');area.id='print-area';area.style.display='none';for(let i=0;i<pages.length;i++){pageIndex=i;render();const img=document.createElement('img');img.src=canvas.toDataURL('image/png');img.alt=pages[i].title||'Teaching page';area.append(img);}pageIndex=previous;render();document.body.append(area);await Promise.all([...area.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));window.print();setTimeout(()=>area.remove(),1500);};}
function validBackup(data,checkingTrash=false){
if(!data||data.version!==1||!Array.isArray(data.pages)||!data.pages.length||data.pages.length>1000)throw Error('Invalid notebook backup (1–1000 pages required).');
const allowed=new Set(['stroke','text','graph','diagram','image','line','rectangle','circle','geometry','livegraph','instrument','conic']);let totalPoints=0;
for(const p of data.pages){if(!p||!Array.isArray(p.objects)||p.objects.length>10000)throw Error('Invalid page data.');
for(const o of p.objects){if(!o||!allowed.has(o.type))throw Error('Unsupported item in backup.');
for(const key of ['x','y','x2','y2','w','h','width','size','lineHeight','maxWidth'])if(key in o&&(!Number.isFinite(o[key])||Math.abs(o[key])>20000))throw Error('Invalid drawing dimensions.');
if(o.type==='text'&&(typeof o.text!=='string'||o.text.length>50000))throw Error('Invalid text item.');
if(o.type==='image'&&(typeof o.src!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(o.src)))throw Error('Only embedded PNG, JPEG or WebP images are supported.');
if(o.type==='stroke'){if(!Array.isArray(o.points)||!o.points.length||o.points.length>200000||!o.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&Math.abs(p.x)<100000&&Math.abs(p.y)<100000&&(!('p' in p)||Number.isFinite(p.p))))throw Error('Invalid pen stroke.');totalPoints+=o.points.length;if(totalPoints>1000000)throw Error('This notebook has too many pen points to import at once.');}
if(o.type==='graph'){MathTools.compile(o.expression);const opt=o.options||{};for(const k of ['xmin','xmax','ymin','ymax'])if(k in opt&&!Number.isFinite(opt[k]))throw Error('Invalid graph bounds.');if(('xmin' in opt&&'xmax' in opt&&opt.xmin>=opt.xmax)||('ymin' in opt&&'ymax' in opt&&opt.ymin>=opt.ymax))throw Error('Invalid graph range.');}
if(o.type==='conic')ConicTools.normalize(o.options);if(o.type==='geometry')GeometryTools.info(o.options);if(o.type==='instrument'&&(!['ruler','protractor'].includes(o.options?.kind)||!Number.isFinite(o.options?.angle)))throw Error('Invalid teaching instrument.');
if(o.type==='livegraph'){checkedBounds(o.options);if(!o.model||!o.params)throw Error('Invalid interactive graph.');if(o.model.kind==='function')MathTools.compile(QuestionGraph.resolve(o.model,o.params));else if(o.model.kind==='circle'){for(const k of ['h','k','r'])if(!Number.isFinite(o.params[k]))throw Error('Invalid circle parameter.');if(o.params.r<0)throw Error('Circle radius cannot be negative.');}else throw Error('Invalid graph type.');}
if(o.type==='diagram'&&!['triangle','parabola','unitcircle','derivative','integral'].includes(o.diagram))throw Error('Invalid illustration type.');
}}
if(!checkingTrash&&data.trashPages!==undefined){if(!Array.isArray(data.trashPages))throw Error('Invalid removed pages.');if(data.trashPages.length)validBackup({version:1,pages:data.trashPages},true);}
return data;
}
$('#backup-input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>50*1024*1024)throw Error('Choose a backup smaller than 50 MB.');const data=validBackup(JSON.parse(await f.text()));pages.push(...data.pages);setPage(pages.length-data.pages.length);closeModal();toast('Backup restored as '+data.pages.length+' additional pages.');}catch(err){toast('Could not restore: '+err.message);}e.target.value='';};$('#export-btn').onclick=exportDialog;
function paperSettings(){const p=current()?.paper||{};return{background:['white','cream','dark'].includes(p.background)?p.background:'white',pattern:['dots','grid','ruled','blank'].includes(p.pattern)?p.pattern:(grid?'dots':'blank'),spacing:Math.max(16,Math.min(80,Number(p.spacing)||32))};}
function visibleInk(color){if(paperSettings().background!=='dark')return color;const match=/^#([0-9a-f]{6})$/i.exec(String(color));if(!match)return color;const rgb=[0,2,4].map(i=>parseInt(match[1].slice(i,i+2),16));if(rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722<130)return'#'+rgb.map(v=>Math.min(240,v+95).toString(16).padStart(2,'0')).join('');return color;}

function updateRecordingFrame(force=false){if(!recordContext||(!force&&!['recording','paused','starting'].includes(recordingState)))return;recordContext.fillStyle=paperSettings().background==='dark'?'#16252b':'#fff';recordContext.fillRect(0,0,1600,1000);recordContext.save();
if(penPrefs.recordView==='view'&&viewport){const r=canvas.getBoundingClientRect(),wr=$('#canvas-wrap').getBoundingClientRect(),scale=Math.min(r.width/1600,r.height/1000),outScale=Math.min(1600/wr.width,1000/wr.height);
if(scale>0&&Number.isFinite(outScale)&&outScale>0){const offsetX=(1600-wr.width*outScale)/2,offsetY=(1000-wr.height*outScale)/2,contentLeft=r.left+(r.width-1600*scale)/2,contentTop=r.top+(r.height-1000*scale)/2;recordContext.beginPath();recordContext.rect(offsetX,offsetY,wr.width*outScale,wr.height*outScale);recordContext.clip();recordContext.drawImage(canvas,offsetX+(contentLeft-wr.left)*outScale,offsetY+(contentTop-wr.top)*outScale,1600*scale*outScale,1000*scale*outScale);if(liveInk)recordContext.drawImage(liveInk.canvas,offsetX+(contentLeft-wr.left)*outScale,offsetY+(contentTop-wr.top)*outScale,1600*scale*outScale,1000*scale*outScale);}else{recordContext.drawImage(canvas,0,0);if(liveInk)recordContext.drawImage(liveInk.canvas,0,0);}
}else{recordContext.drawImage(canvas,0,0);if(liveInk)recordContext.drawImage(liveInk.canvas,0,0);}recordContext.restore();}

function drawPenCursor(e){const c=$('#pen-cursor')?.getContext('2d');if(!c)return;c.clearRect(0,0,1600,1000);if(!cursorPoint||!penPrefs.hover||['select','lasso','hand','text','laser','spotlight'].includes(tool))return;const erase=gestureTool==='eraser'||tool==='eraser'||(e&&contactTool(e)==='eraser'),radius=erase?penPrefs.eraserSize:Math.max(3,width/2);c.save();c.strokeStyle=paperSettings().background==='dark'?'#d6e8b8':'#5a8260';c.lineWidth=1.6;c.setLineDash(erase?[6,4]:[]);c.beginPath();c.arc(cursorPoint.x,cursorPoint.y,radius,0,Math.PI*2);c.stroke();c.restore();}
