function updatePenStatus(){const only=$('#pen-only').checked;$('#pen-mode-status').textContent=only?'✎ S Pen only · haath se ink blocked':'✋ Finger writing ON';document.body.classList.toggle('spen-mode',only);document.body.classList.toggle('left-handed',penPrefs.leftHanded);for(let i=0;i<3;i++){const p=penPrefs.favorites[i],b=$('#favorite-pen-'+i);if(b&&p){b.style.color=p.color;b.title=p.style+' · '+p.width+' px';}}}
