liveInk=new InkSurface($('#ink-live'),PenEngine);penPrefs.opacity=Math.max(.2,Math.min(1,Number(penPrefs.opacity)||1));if(!Array.isArray(penPrefs.favorites)||penPrefs.favorites.length<3)penPrefs.favorites=[{style:'ballpoint',color:'#243b3a',width:4},{style:'fountain',color:'#147d72',width:5},{style:'pencil',color:'#516ace',width:4}];penPrefs.eraserSize=Math.max(5,Math.min(100,Number(penPrefs.eraserSize)||24));penPrefs.eraserMode=penPrefs.eraserMode==='segment'?'segment':'stroke';$('#pen-width').value=width;$('#width-preview').textContent=width;$('#record-view').value=penPrefs.recordView==='full'?'full':'view';effects=new TeacherEffects({render:()=>render(false)});$('.board-header-actions').append($('#exit-focus'));window.addEventListener('resize',fitTeachingLayout);
