function initializeLasso(){lasso=new LassoTool($('#selection-overlay'),{getObjects:()=>current()?.objects||[],bounds:o=>editor.bounds(o),checkpoint:pushHistory,render,save,onSelect:objects=>{if(tool!=='lasso')return;$('#selection-label').textContent=objects.length?objects.length+' objects selected · drag group / Duplicate / Delete':'Lasso: likhawat ya objects ke aas-paas loop banaiye.';$('#selection-duplicate').disabled=!objects.length;$('#selection-delete').disabled=!objects.length;$('#selection-edit').hidden=true;updateSelectionActions();renderSelectedControls(null);}});$('#selection-duplicate').onclick=()=>{if(tool==='lasso')lasso.duplicate();else editor.duplicate();};$('#selection-delete').onclick=()=>{if(tool==='lasso')lasso.remove();else editor.remove();};}
function spenSettings(){openModal('Aapka S Pen. Aapki writing style.',`<p class="modal-intro">Chrome mein palm ink rokne ke liye S Pen only default ON hai. Two fingers se zoom/pan karein; ek ungli se pan ke liye Hand tool chunein.</p><div class="spen-settings-grid"><section class="spen-setting"><h3>Pen & handwriting</h3><div class="pen-presets">${['ballpoint','fountain','pencil','calligraphy'].map(p=>'<button data-pen-style="'+p+'" class="'+(penSettings.style===p?'selected':'')+'">✎ '+p[0].toUpperCase()+p.slice(1)+'</button>').join('')}</div><label class="spen-toggle"><input id="spen-only-setting" type="checkbox" ${$('#pen-only').checked?'checked':''}> S Pen only · finger / palm ink blocked</label><label class="spen-toggle"><input id="spen-pressure" type="checkbox" ${penSettings.pressure?'checked':''}> Pressure-based line width</label><label class="field">Pressure sensitivity <span id="pressure-value">${penSettings.sensitivity}</span><input id="spen-sensitivity" type="range" min="0.25" max="3" step="0.05" value="${penSettings.sensitivity}"></label><label class="field">Writing smoothing <span id="smoothing-value">${penSettings.smoothing}</span><input id="spen-smoothing" type="range" min="0" max="0.9" step="0.05" value="${penSettings.smoothing}"></label><label class="field">Eraser mode<select id="spen-eraser-mode"><option value="stroke">Whole stroke</option><option value="segment">Rub out only the touched part</option></select></label><label class="field">Eraser radius <input id="spen-eraser-size" type="range" min="5" max="100" value="${penPrefs.eraserSize}"></label><label class="field">Side-button shortcut, if browser reports it<select id="spen-side-button"><option value="eraser">Hold = eraser, release = pen</option><option value="none">No shortcut</option></select></label><label class="spen-toggle"><input id="spen-hover" type="checkbox" ${penPrefs.hover?'checked':''}> Show pen / eraser cursor</label><label class="spen-toggle"><input id="spen-autoshape" type="checkbox" ${penPrefs.autoShape?'checked':''}> Turn simple drawn shapes into clean shapes</label><label class="spen-toggle"><input id="spen-angle" type="checkbox" ${penPrefs.angleSnap?'checked':''}> Straight-line tool: snap to 15°</label><label class="spen-toggle"><input id="spen-left" type="checkbox" ${penPrefs.leftHanded?'checked':''}> Left-handed toolbar</label><label class="spen-toggle"><input id="spen-awake" type="checkbox" ${wakeLock?'checked':''}> Keep screen awake while teaching</label><p id="awake-status" class="pen-diagnostic-note"></p><div class="modal-actions"><button class="button outline" id="save-favourite">Current pen ko favourite 1 banayein</button></div></section><section class="spen-setting"><h3>S Pen live test</h3><p class="pen-diagnostic-note">Halka/daba kar likhiye, pen jhukayein, tip ko screen ke paas laayein aur side button dabayein. Neeche browser ka actual data dikhega.</p><div style="position:relative;margin-top:13px;border:1px solid #dce6d0;border-radius:7px;overflow:hidden"><canvas class="pen-test-canvas" id="pen-test" width="700" height="410" style="margin:0;border:0"></canvas><canvas id="pen-test-live" width="700" height="410" aria-hidden="true" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"></canvas></div><div class="spen-diagnostics"><div>Input<strong id="diag-input">Waiting</strong></div><div>Pressure<strong id="diag-pressure">—</strong></div><div>Buttons<strong id="diag-buttons">—</strong></div><div>Tilt X<strong id="diag-tiltx">—</strong></div><div>Tilt Y<strong id="diag-tilty">—</strong></div><div>Shortcut<strong id="diag-shortcut">—</strong></div></div><button class="button quiet" id="clear-pen-test" style="margin-top:12px">Clear test pad</button><div class="notice">Pressure, tilt, hover aur side-button browser jitna data bhejta hai utna hi use hoga. Bluetooth Air actions / Air Command web app se control nahi hote. Text box mein Samsung Keyboard ka handwriting input, agar available ho, use kar sakte hain.</div></section></div>`,'S PEN STUDIO');$('#modal').classList.add('modal-wide');$('#spen-eraser-mode').value=penPrefs.eraserMode;$('#spen-side-button').value=penPrefs.sideButton;
function changed(){penSettings=PenEngine.normalizeSettings({...penSettings,pressure:$('#spen-pressure').checked,sensitivity:+$('#spen-sensitivity').value,smoothing:+$('#spen-smoothing').value});penPrefs.eraserMode=$('#spen-eraser-mode').value;penPrefs.eraserSize=+$('#spen-eraser-size').value;penPrefs.sideButton=$('#spen-side-button').value;penPrefs.hover=$('#spen-hover').checked;penPrefs.autoShape=$('#spen-autoshape').checked;penPrefs.angleSnap=$('#spen-angle').checked;penPrefs.leftHanded=$('#spen-left').checked;$('#pen-only').checked=$('#spen-only-setting').checked;$('#pressure-value').textContent=penSettings.sensitivity;$('#smoothing-value').textContent=penSettings.smoothing;updatePenStatus();storePenPreferences();}
for(const id of ['spen-only-setting','spen-pressure','spen-sensitivity','spen-smoothing','spen-eraser-mode','spen-eraser-size','spen-side-button','spen-hover','spen-autoshape','spen-angle','spen-left'])$('#'+id).oninput=changed;$$('[data-pen-style]').forEach(b=>b.onclick=()=>{penSettings.style=b.dataset.penStyle;$$('[data-pen-style]').forEach(x=>x.classList.toggle('selected',x===b));storePenPreferences();});$('#save-favourite').onclick=()=>{penPrefs.favorites[0]={style:penSettings.style,color:ink,width};updatePenStatus();storePenPreferences();toast('Current pen favourite 1 mein save ho gaya.');};$('#spen-awake').onchange=async e=>{if(!e.target.checked){try{await wakeLock?.release();}catch{}wakeLock=null;$('#awake-status').textContent='Screen wake lock off.';return;}try{if(!navigator.wakeLock)throw Error('Screen wake lock is not available in this browser.');wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener?.('release',()=>{wakeLock=null;});$('#awake-status').textContent='Screen awake hai. Background mein jaane par browser lock release kar sakta hai.';}catch(err){e.target.checked=false;$('#awake-status').textContent=err.message;}};
const pad=$('#pen-test'),pc=pad.getContext('2d'),padInk=new InkSurface($('#pen-test-live'),PenEngine);let stroke=null,id=null;const clear=()=>{stroke=null;id=null;padInk.clear();pc.fillStyle='#fff';pc.fillRect(0,0,700,410);};clear();function metrics(e){const p=PenEngine.point(e);$('#diag-input').textContent=e.pointerType||'mouse';$('#diag-pressure').textContent=p.pressureSupported?p.p.toFixed(3):'No data';$('#diag-buttons').textContent=String(e.buttons||0);$('#diag-tiltx').textContent=p.tiltX+'°';$('#diag-tilty').textContent=p.tiltY+'°';$('#diag-shortcut').textContent=PenEngine.isEraser(e)?'Eraser':PenEngine.isSideButton(e)?'Side button':'—';const r=pad.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*700,y:(e.clientY-r.top)/r.height*410,...p};}pad.onpointerdown=e=>{e.preventDefault();const p=metrics(e);if(e.pointerType==='touch'||id!==null)return;if(e.pointerType==='pen'&&e.pressure===0&&!(e.buttons&1)&&!PenEngine.isEraser(e))return;id=e.pointerId;try{pad.setPointerCapture(id);}catch{}stroke=PenEngine.createStroke({tool:PenEngine.isEraser(e)?'eraser':'pen',color:ink,width,opacity:penPrefs.opacity,settings:penSettings},p);padInk.begin(stroke);};pad.onpointermove=e=>{const p=metrics(e);if(stroke&&e.pointerId===id){PenEngine.append(stroke,p);padInk.update(stroke);}};pad.onpointerup=pad.onpointercancel=e=>{if(!stroke||e.pointerId!==id)return;if(Number.isFinite(e.clientX)&&Number.isFinite(e.clientY))PenEngine.append(stroke,metrics(e));padInk.finish(stroke);PenEngine.draw(pc,stroke);padInk.clear();stroke=null;id=null;};pad.oncontextmenu=e=>e.preventDefault();$('#clear-pen-test').onclick=clear;
}
function paperDialog(){const options=paperSettings();openModal('Board ko apni class ke hisaab se rakhein.',`<p class="modal-intro">Paper har page ke saath save hota hai. Purani writing aur images apni jagah rahengi.</p><div class="paper-choice-grid">${['dots','grid','ruled','blank'].map(p=>'<button class="paper-choice '+(options.pattern===p?'selected':'')+'" data-paper-pattern="'+p+'">'+p.toUpperCase()+'</button>').join('')}</div><div class="paper-swatches"><button data-paper-bg="white" style="background:#fff">White board</button><button data-paper-bg="cream" style="background:#fff9e8">Warm paper</button><button data-paper-bg="dark" style="background:#20372f;color:#e7f0d8">Dark board</button></div><label class="field">Line / grid spacing<input type="range" id="paper-spacing" min="16" max="80" value="${options.spacing}"></label><div class="notice">Dark board par dark pen strokes halka rang use karenge. PDF aur graph cards apne asli colors mein rahenge.</div>`,'PAPER & BOARD');$$('[data-paper-pattern]').forEach(b=>b.onclick=()=>{options.pattern=b.dataset.paperPattern;apply();$$('[data-paper-pattern]').forEach(x=>x.classList.toggle('selected',x===b));});$$('[data-paper-bg]').forEach(b=>b.onclick=()=>{options.background=b.dataset.paperBg;apply();});$('#paper-spacing').oninput=e=>{options.spacing=+e.target.value;apply();};function apply(){current().paper={...options};$('#grid-toggle').checked=options.pattern!=='blank';render();save();}}
function instrumentsDialog(){openModal('Measure. Mark. Explain.','<p class="modal-intro">Ruler ya protractor board par lagaiye. Select se move/resize karein. Ruler ka cm board scale hai, tablet ka physical centimetre nahi.</p><div class="input-row"><label class="field">Instrument<select id="instrument-kind"><option value="ruler">Ruler</option><option value="protractor">Protractor</option></select></label><label class="field">Rotation (degrees)<input type="number" id="instrument-angle" value="0" min="-360" max="360"></label></div><canvas class="instruments-preview" id="instrument-preview" width="1000" height="500"></canvas><div class="modal-actions"><button class="button primary" id="instrument-add">Board par lagayein</button></div>','TEACHING INSTRUMENTS');const draw=()=>{const angle=Number($('#instrument-angle').value);if(Number.isFinite(angle))TeachingTools.drawInstrument($('#instrument-preview').getContext('2d'),{x:0,y:0,w:1000,h:500},{kind:$('#instrument-kind').value,angle});};$('#instrument-kind').onchange=draw;$('#instrument-angle').oninput=draw;$('#instrument-add').onclick=()=>{const angle=Number($('#instrument-angle').value);if(!Number.isFinite(angle))return;pushHistory();current().objects.push({type:'instrument',x:260,y:230,w:1080,h:540,options:{kind:$('#instrument-kind').value,angle}});render();save();closeModal();selectObject(current().objects.length-1);};draw();}
let timerState={remaining:300,running:false,deadline:0},timerInterval=null;
function timerUpdate(){if(timerState.running)timerState.remaining=Math.max(0,Math.ceil((timerState.deadline-Date.now())/1000));$('#timer-display').textContent=timeText(timerState.remaining);$('#timer-toggle').textContent=timerState.running?'Ⅱ':'▶';$('#class-timer').classList.toggle('finished',timerState.remaining===0);if(timerState.running&&timerState.remaining===0){timerState.running=false;clearInterval(timerInterval);timerInterval=null;toast('Time complete. Class ke answers discuss karein.');}}
function timerToggle(){if(timerState.running){timerUpdate();timerState.running=false;clearInterval(timerInterval);timerInterval=null;}else{if(timerState.remaining<=0)timerState.remaining=300;timerState.running=true;timerState.deadline=Date.now()+timerState.remaining*1000;timerInterval=setInterval(timerUpdate,300);}timerUpdate();}
$('#timer-toggle').onclick=timerToggle;$('#timer-hide').onclick=()=>{if(timerState.running)timerToggle();$('#class-timer').hidden=true;};
function timerDialog(){openModal('Class ko ek clear rhythm dein.','<p class="modal-intro">Practice, test ya think-time ke liye countdown. Timer board ke bahar dikhega; video mein board hi record hota hai.</p><div class="timer-inputs"><label class="field">Minutes<input id="timer-minutes" type="number" min="0" max="180" value="5"></label><label class="field">Seconds<input id="timer-seconds" type="number" min="0" max="59" value="0"></label></div><div class="modal-actions"><button class="button primary" id="timer-start">Start timer</button><button class="button outline" id="timer-show">Show current timer</button></div>','CLASS TIMER');$('#timer-start').onclick=()=>{const m=Number($('#timer-minutes').value),s=Number($('#timer-seconds').value);if(!Number.isInteger(m)||!Number.isInteger(s)||m<0||m>180||s<0||s>59||m*60+s===0)return toast('Valid time chuniye: 1 second se 180 minutes tak.');clearInterval(timerInterval);timerState={remaining:m*60+s,running:false,deadline:0};$('#class-timer').hidden=false;timerToggle();closeModal();};$('#timer-show').onclick=()=>{$('#class-timer').hidden=false;timerUpdate();closeModal();};}
function notebook(){const before=pageIndex,thumbs=[];if(recordingState==='idle'){for(let i=0;i<pages.length;i++){pageIndex=i;render();const t=document.createElement('canvas');t.width=320;t.height=200;t.getContext('2d').drawImage(canvas,0,0,320,200);thumbs.push(t.toDataURL('image/png'));}pageIndex=before;render();}
openModal('Har page, aapke control mein.','<p class="modal-intro">Pages ko rename, arrange aur duplicate karein. Removed pages neeche se restore kar sakte hain. Notebook backup mein pages, drawings aur paper settings save hote hain.</p><div class="page-thumbnail-list">'+pages.map((p,i)=>'<article class="page-thumbnail-card">'+(thumbs[i]?'<img src="'+thumbs[i]+'" alt="Page '+(i+1)+' preview">':'<p class="notice">Page '+(i+1)+'</p>')+'<input data-page-title="'+i+'" aria-label="Page '+(i+1)+' title" value="'+esc(p.title||'Teaching page')+'"><div class="page-thumbnail-actions"><button data-page-open="'+i+'">Open</button><button data-page-up="'+i+'" '+(i===0?'disabled':'')+'>↑</button><button data-page-down="'+i+'" '+(i===pages.length-1?'disabled':'')+'>↓</button><button data-page-copy="'+i+'">Duplicate</button><button data-page-remove="'+i+'">Remove</button></div></article>').join('')+'</div><div class="modal-actions"><button class="button primary" id="notebook-new-page">＋ Blank page</button><button class="button outline" id="notebook-backup">Backup / export</button></div><div class="trash-pages"><h3 class="modal-subhead">Removed pages ('+trashPages.length+')</h3>'+trashPages.map((p,i)=>'<div class="notebook-page"><span>'+esc(p.title||'Teaching page')+'</span><button class="button quiet" data-page-restore="'+i+'">Restore</button></div>').join('')+'</div>','NOTEBOOK ORGANIZER');$('#modal').classList.add('modal-wide');$$('[data-page-title]').forEach(i=>i.onchange=()=>{pages[+i.dataset.pageTitle].title=i.value;if(+i.dataset.pageTitle===pageIndex)$('#board-title').value=i.value;save();});$$('[data-page-open]').forEach(b=>b.onclick=()=>{setPage(+b.dataset.pageOpen);closeModal();});
function arrange(from,to){const id=current().id;[pages[from],pages[to]]=[pages[to],pages[from]];setPage(pages.findIndex(p=>p.id===id));notebook();}
$$('[data-page-up]').forEach(b=>b.onclick=()=>arrange(+b.dataset.pageUp,+b.dataset.pageUp-1));$$('[data-page-down]').forEach(b=>b.onclick=()=>arrange(+b.dataset.pageDown,+b.dataset.pageDown+1));$$('[data-page-copy]').forEach(b=>b.onclick=()=>{const p=JSON.parse(JSON.stringify(pages[+b.dataset.pageCopy]));p.id=Date.now()+'-'+Math.random().toString(16).slice(2);p.title+=' · copy';pages.splice(+b.dataset.pageCopy+1,0,p);setPage(+b.dataset.pageCopy+1);notebook();});$$('[data-page-remove]').forEach(b=>b.onclick=()=>{const index=+b.dataset.pageRemove;trashPages.push(pages.splice(index,1)[0]);if(!pages.length)pages.push({id:Date.now()+'',title:'Blank page',objects:[]});setPage(Math.min(pageIndex,pages.length-1));notebook();});$$('[data-page-restore]').forEach(b=>b.onclick=()=>{pages.push(trashPages.splice(+b.dataset.pageRestore,1)[0]);setPage(pages.length-1);notebook();});$('#notebook-new-page').onclick=()=>{addBlank();closeModal();};$('#notebook-backup').onclick=exportDialog;
}
