function timeText(seconds){return Math.floor(seconds/60).toString().padStart(2,'0')+':'+Math.floor(seconds%60).toString().padStart(2,'0');}
const recorder=new StudioRecorder(recordCanvas,{onState:s=>{recordingState=s.state;const active=['recording','paused'].includes(s.state);$('.record-bar').classList.toggle('recording',active);$('#record-time').textContent=timeText(s.seconds);$('#record-time').hidden=!active;$('#pause-record').hidden=!active;$('#pause-record').textContent=s.state==='paused'?'Resume':'Pause';$('#mic-toggle').disabled=s.state!=='idle';$('#record-btn').disabled=['starting','stopping'].includes(s.state);$('#record-btn').innerHTML=s.state==='idle'?'<span class="red-dot"></span> Start recording':s.state==='starting'?'Starting…':s.state==='stopping'?'Saving…':'<span class="red-dot"></span> Stop & save';$('#record-label').textContent=active?(s.state==='paused'?'Recording paused. Take your time.':'Your lesson is being recorded.'):'Great lessons deserve a replay.';$('#record-subtitle').textContent=active?(s.microphone?'Board + microphone · keep this app visible':'Board only · microphone is off'):'Record your board + voice. Teach online or offline.';if(active)render(false);},onSaved:meta=>{lastRecording=meta;updateRecordingCount();recordingSaved(meta);},onError:err=>toast(err.message||String(err))});
$('#record-btn').onclick=async()=>{try{updateRecordingFrame(true);if(['recording','paused'].includes(recordingState)){await recorder.stop();}else if(recordingState==='idle'){await recorder.start({microphone:$('#mic-toggle').checked,metadata:{name:activeNoteTitle+' · '+$('#board-title').value,lessonTitle:$('#board-title').value,notebookName:activeNoteTitle,notebookId:activeNoteId||'',classLevel:level}});toast($('#mic-toggle').checked?'Recording your board and microphone.':'Recording your board without audio.');}}catch(e){toast(e.message+' You can turn Mic off and try again.');}};
