function updateNetwork(){const online=navigator.onLine;$('#network-status').innerHTML='<i></i> '+(online?'Online':'Offline');$('#network-status').classList.toggle('offline',!online);updateClassroomStatus();}window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
function updateClassroomStatus(){const ready=$('#offline-ready').textContent.toLowerCase().includes('offline ready');$('#classroom-status').textContent=navigator.onLine?(ready?'● Offline ready':'● Online'):(ready?'● Offline · ready':'● Offline');}
async function offlineSetup(){
 if(!('serviceWorker' in navigator)){$('#offline-ready').textContent='Offline cache unavailable';updateClassroomStatus();return;}
 try{let registration;try{registration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});if(navigator.onLine)try{await registration.update();}catch{}}catch(e){registration=await navigator.serviceWorker.getRegistration('./');if(!registration)throw e;}
 const worker=registration.installing||registration.waiting;if(worker&&worker.state!=='activated')await new Promise((resolve,reject)=>{const change=()=>{if(worker.state==='activated')resolve();if(worker.state==='redundant')reject(Error('Offline update failed.'));};worker.addEventListener('statechange',change);change();});
 const cache=await caches.open('ganit-studio-v9');const ready=await Promise.all(['./index.html','./app.js?v=9','./pen-engine.js?v=9','./ink-surface.js?v=9','./vendor/pdfjs/pdf.worker.min.mjs'].map(path=>cache.match(path)));$('#offline-ready').textContent=ready.every(Boolean)?'Offline ready':'Offline update downloading…';
 }catch(e){$('#offline-ready').textContent='Open online to enable offline';}updateClassroomStatus();
}
