let activeNoteId=null,activeNoteTitle='Meri teaching notebook',notesAvailable=false,boardClipboard=[],saveQueue=Promise.resolve();
async function persistSnapshot(state,revision,noteId=activeNoteId){
 saveQueue=saveQueue.catch(()=>{}).then(async()=>{await dbSave(state);if(notesAvailable&&noteId)await NotesLibrary.saveNote(noteId,state);if(revision===saveRevision)$('#save-status').innerHTML='<svg><use href="#i-check"/></svg> Saved';});
 try{await saveQueue;}catch(e){$('#save-status').textContent='Save failed';toast('Storage bhar gaya ya available nahi hai. Notebook backup download karein.');throw e;}
}
function flushSave(){clearTimeout(saveTimer);saveTimer=null;const revision=++saveRevision;return persistSnapshot(snapshot(),revision);}
